def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    op.add_column('items', sa.Column('position', sa.Integer(), server_default=sa.text('0'), nullable=False))
    # ### end Alembic commands ###
    # Added by hand: number existing items 0,1,2... per batch (best guess of upload order).
    # Concept: WINDOW FUNCTION. ROW_NUMBER() OVER (PARTITION BY batch_id ...) restarts
    # the count for each batch, like a per-group counter.
    # Example: batch A has 3 items -> 0,1,2; batch B has 2 -> 0,1
    op.execute("""
        UPDATE items SET position = numbered.rn - 1
        FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY batch_id ORDER BY created_at, id) AS rn
              FROM items) AS numbered
        WHERE items.id = numbered.id
    """)


